#include <iostream>
#include <vector>
#include <functional>
using namespace std;

class Pipeline {
    vector<function<int(int)>> transforms;
public:
    void addTransform(function<int(int)> fn) { transforms.push_back(fn); }

    int execute(int input) {
        for (auto& fn : transforms) input = fn(input);
        return input;
    }
};

int main() {
    Pipeline p;
    p.addTransform([](int x) { return x < 0 ? -x : x; }); // absolute
    p.addTransform([](int x) { return x * 2; });          // double
    p.addTransform([](int x) { return x + 1; });          // increment
    cout << "Result: " << p.execute(-3) << endl;
    return 0;
}
